const {request,chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const base='http://127.0.0.1:4183',r=await request.newContext(),res=[];let cid;const record=(name,ok,detail)=>{res.push({name,ok,detail});console.log(name,ok,JSON.stringify(detail));if(!ok)throw Error(name)};const call=async(path,method='GET',data,headers={})=>{const a=await r.fetch(base+path,{method,data,headers});return {status:a.status(),data:await a.json().catch(()=>({}))}};
try{const auth=await call('/api/admin/v1/auth/login','POST',{email:'admin@dracula-food.com',password:'Dracula121.'});const h={Authorization:'Bearer '+auth.data.access_token};const cats=await call('/api/admin/v1/categories','GET',undefined,h);const pantry=cats.data.items.find(c=>c.external_id==='pantry');record('pantry count',pantry.product_count===2,pantry.product_count);
const create=await call('/api/admin/v1/categories','POST',{name:{ro:'QA Food Regression'},is_active:true},h);cid=create.data.id;record('category create',create.status===201,create.status);const code=create.data.external_id;let boot=await call('/api/dracula/bootstrap');record('active visible',boot.data.categories.some(c=>c.code===code),code);await call('/api/admin/v1/categories/'+cid,'PATCH',{is_active:false},h);boot=await call('/api/dracula/bootstrap');record('inactive hidden',!boot.data.categories.some(c=>c.code===code),code);await call('/api/admin/v1/categories/'+cid+'?hard=1','DELETE',undefined,h);cid=null;
await call('/api/cart');const cookies=(await r.storageState()).cookies;const csrf=cookies.find(c=>c.name==='dracula_food_csrf')?.value;const head={'X-CSRF-Token':csrf};for(const qty of ['invalid',-1,1.5,true,{}]){const a=await call('/api/cart/items','POST',{product_id:'nuci-dracula-farm',qty},head);record('reject qty '+JSON.stringify(qty),a.status===400,a)}const sync=await call('/api/cart/sync','POST',{items:[{product_id:'nuci-dracula-farm',qty:1},{product_id:'alune-de-padure-dracula-farm',qty:'bad'}]},head);record('sync rejects all',sync.status===400,sync);const cart=await call('/api/cart');record('invalid requests left empty cart',cart.data.items_count===0,cart.data.items_count);
await call('/api/account/login','POST',{email:'client@dracula-food.com',password:'Dracula121.'});const cookies2=(await r.storageState()).cookies;const head2={'X-CSRF-Token':cookies2.find(c=>c.name==='dracula_food_csrf')?.value,'Idempotency-Key':'qa_food_badtotal_regression'};const order=await call('/api/orders','POST',{customer:{first_name:'QA',last_name:'Audit',email:'client@dracula-food.com',phone:'0722123456'},shipping_address:{line1:'QA 1',city:'Brasov',county:'Brasov',postal_code:'500001',country:'RO'},payment_method:'bank_transfer',delivery_method:'courier',accept_terms:true,expected_total_ron:'NaN'},head2);record('NaN total rejected',order.status===400,order);
const b=await chromium.launch();const p=await b.newPage({viewport:{width:390,height:844}});try{await p.goto(base+'/ro/product/nuci-dracula-farm');await p.locator('[data-action=image]').click();const label=await p.locator('dialog').getAttribute('aria-label');record('dialog named',!!label,label);await p.keyboard.press('Escape');await p.goto(base+'/ro/collection');await p.locator('.filters').waitFor();record('filter all pressed',(await p.locator('[data-filter=all]').getAttribute('aria-pressed'))==='true');await p.locator('[data-filter=stafide-naturale]').click();record('filter changes pressed',(await p.locator('[data-filter=stafide-naturale]').getAttribute('aria-pressed'))==='true'&&(await p.locator('[data-filter=all]').getAttribute('aria-pressed'))==='false');}finally{await b.close()}
}catch(e){res.push({failure:e.stack});console.error(e)}finally{if(cid){const a=await call('/api/admin/v1/auth/login','POST',{email:'admin@dracula-food.com',password:'Dracula121.'});await call('/api/admin/v1/categories/'+cid+'?hard=1','DELETE',undefined,{Authorization:'Bearer '+a.data.access_token})}fs.writeFileSync('work/audit-food-regression-results.json',JSON.stringify(res,null,2));await r.dispose()}})();
